var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.linkmobility.com/sms/v1/messages"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
    Content = new StringContent("[{\"recipient\":\"string\",\"content\":{\"text\":\"string\",\"options\":{\"sms.encoding\":\"AutoDetect\",\"sms.sender\":\"string\",\"sms.obfuscate\":\"ContentAndRecipient\"}},\"expiration\":{\"relative\":1,\"absolute\":\"2019-08-24T14:15:22Z\"},\"callback\":{\"mode\":\"Profile\",\"urls\":[\"string\"],\"gateId\":\"string\",\"ttl\":28800000},\"referenceId\":\"string\",\"priority\":\"Normal\"}]")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const http = require("https");

const options = {
  "method": "POST",
  "hostname": "api.linkmobility.com",
  "port": null,
  "path": "/sms/v1/messages",
  "headers": {
    "content-type": "application/json",
    "Authorization": "Bearer REPLACE_BEARER_TOKEN"
  }
};

const req = http.request(options, function (res) {
  const chunks = [];

  res.on("data", function (chunk) {
    chunks.push(chunk);
  });

  res.on("end", function () {
    const body = Buffer.concat(chunks);
    console.log(body.toString());
  });
});

req.write(JSON.stringify([
  {
    recipient: 'string',
    content: {
      text: 'string',
      options: {
        'sms.encoding': 'AutoDetect',
        'sms.sender': 'string',
        'sms.obfuscate': 'ContentAndRecipient'
      }
    },
    expiration: {relative: 1, absolute: '2019-08-24T14:15:22Z'},
    callback: {mode: 'Profile', urls: ['string'], gateId: 'string', ttl: 28800000},
    referenceId: 'string',
    priority: 'Normal'
  }
]));
req.end();

